export type PaletteTag =
  | 'warm'
  | 'cool'
  | 'neutral'
  | 'dark'
  | 'light'
  | 'vibrant'
  | 'muted'
  | 'pastel'
  | 'earthy'
  | 'monochrome'
  | 'high-contrast'
  | 'low-contrast'
  | 'red'
  | 'orange'
  | 'yellow'
  | 'green'
  | 'teal'
  | 'blue'
  | 'purple'
  | 'pink';

export interface Palette {
  id: string;
  name: string;
  colors: string[];
  tags: PaletteTag[];
}

export const PALETTE_TAG_LABELS: Record<PaletteTag, string> = {
  warm: 'Warm',
  cool: 'Cool',
  neutral: 'Neutral',
  dark: 'Dark',
  light: 'Light',
  vibrant: 'Vibrant',
  muted: 'Muted',
  pastel: 'Pastel',
  earthy: 'Earthy',
  monochrome: 'Monochrome',
  'high-contrast': 'High Contrast',
  'low-contrast': 'Low Contrast',
  red: 'Red',
  orange: 'Orange',
  yellow: 'Yellow',
  green: 'Green',
  teal: 'Teal',
  blue: 'Blue',
  purple: 'Purple',
  pink: 'Pink',
};

// Mood/character — palette-level feel, computed from average saturation/lightness/hue.
export const STYLE_TAG_ORDER: PaletteTag[] = [
  'warm',
  'cool',
  'vibrant',
  'earthy',
  'light',
  'dark',
  'muted',
  'pastel',
  'monochrome',
  'neutral',
];

// Dominant hue family — computed the same way as the palette's generated name.
export const HUE_TAG_ORDER: PaletteTag[] = [
  'red',
  'orange',
  'yellow',
  'green',
  'teal',
  'blue',
  'purple',
  'pink',
];

// Spread between the lightest and darkest of the 5 colors (top/bottom quartile).
export const CONTRAST_TAG_ORDER: PaletteTag[] = ['high-contrast', 'low-contrast'];

export const PALETTE_TAG_ORDER: PaletteTag[] = [...STYLE_TAG_ORDER, ...HUE_TAG_ORDER, ...CONTRAST_TAG_ORDER];
