import type { FC } from 'react';
import { useState } from 'react';
import { toast } from 'sonner';
import { getContrastText } from '@/lib/palette/export';

interface PaletteSwatchProps {
  hex: string;
}

// Hover feedback uses only transform/opacity (compositor-only properties) so
// it stays smooth with 240 palettes (1200+ swatches) on the page at once.
// Animating flex-grow/width instead forces a synchronous layout recalc on
// every frame — that's what was reading as stuttery, not a duration/easing
// problem. origin-bottom keeps the hex label's anchor point stable while the
// swatch "lifts" upward into view.
const PaletteSwatch: FC<PaletteSwatchProps> = ({ hex }) => {
  const [isHovered, setIsHovered] = useState(false);
  const textColor = getContrastText(hex);

  const handleClick = async () => {
    try {
      await navigator.clipboard.writeText(hex);
      toast.success(`Copied ${hex}`);
    } catch {
      toast.error('Copy failed');
    }
  };

  return (
    <div
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={handleClick}
      role="button"
      tabIndex={0}
      aria-label={`Copy ${hex}`}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleClick();
        }
      }}
      style={{ backgroundColor: hex }}
      className={`relative flex-1 basis-0 min-w-0 flex items-end justify-center pb-2 origin-bottom cursor-pointer transition-transform duration-200 ease-out ${
        isHovered ? 'z-10 scale-[1.06] shadow-[0_6px_18px_rgba(0,0,0,0.35)]' : 'scale-100'
      }`}
    >
      <span
        style={{
          color: textColor,
          backgroundColor: textColor === '#ffffff' ? 'rgba(0,0,0,0.28)' : 'rgba(255,255,255,0.35)',
        }}
        className={`text-[10px] font-mono px-1.5 py-0.5 rounded whitespace-nowrap transition-[opacity,transform] duration-200 ease-out ${
          isHovered ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-1'
        }`}
      >
        {hex.toUpperCase()}
      </span>
    </div>
  );
};

export default PaletteSwatch;
