import type { FC } from 'react';
import { useState } from 'react';
import { toast } from 'sonner';
import { Copy, Check, Code2 } from 'lucide-react';
import { PALETTE_TAG_LABELS, type Palette } from '@/lib/palette/types';
import { buildCssSnippet, buildPlainList } from '@/lib/palette/export';
import PaletteSwatch from './PaletteSwatch';

interface PaletteCardProps {
  palette: Palette;
}

const buttonBase =
  'flex-1 inline-flex items-center justify-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium border border-border text-foreground/70 hover:text-foreground hover:border-accent/40 transition-colors';

const PaletteCard: FC<PaletteCardProps> = ({ palette }) => {
  const [copiedKind, setCopiedKind] = useState<'list' | 'css' | null>(null);

  const handleCopy = async (kind: 'list' | 'css') => {
    const text = kind === 'list' ? buildPlainList(palette) : buildCssSnippet(palette);
    try {
      await navigator.clipboard.writeText(text);
      setCopiedKind(kind);
      toast.success(kind === 'list' ? 'Copied colors' : 'Copied CSS');
      window.setTimeout(() => setCopiedKind((current) => (current === kind ? null : current)), 1500);
    } catch {
      toast.error('Copy failed');
    }
  };

  return (
    <div className="glass-panel hover:border-border overflow-hidden flex flex-col">
      <div className="flex h-28 sm:h-32">
        {palette.colors.map((hex, i) => (
          <PaletteSwatch key={`${palette.id}-${i}`} hex={hex} />
        ))}
      </div>
      <div className="p-3 flex flex-col gap-2.5">
        <div className="flex items-center justify-between gap-2">
          <p className="text-sm font-medium text-foreground truncate">{palette.name}</p>
          <span className="shrink-0 px-2 py-0.5 text-[10px] font-medium rounded-full bg-background/50 text-accent border border-accent/30">
            {PALETTE_TAG_LABELS[palette.tags[0]]}
          </span>
        </div>
        <div className="flex gap-2">
          <button type="button" onClick={() => handleCopy('list')} className={buttonBase}>
            {copiedKind === 'list' ? <Check className="w-3.5 h-3.5 text-accent" /> : <Copy className="w-3.5 h-3.5" />}
            Copy All
          </button>
          <button type="button" onClick={() => handleCopy('css')} className={buttonBase}>
            {copiedKind === 'css' ? <Check className="w-3.5 h-3.5 text-accent" /> : <Code2 className="w-3.5 h-3.5" />}
            Copy CSS
          </button>
        </div>
      </div>
    </div>
  );
};

export default PaletteCard;
