import type { Palette } from './types';

/** Plain comma-separated hex list — pasteable anywhere, no wrapper. */
export function buildPlainList(palette: Palette): string {
  return palette.colors.join(', ');
}

/** CSS custom-property block, e.g.:
 *  /* Mayfair *\/
 *  --color-1: #1a2634;
 *  --color-2: #2d4a3e;
 *  ...
 */
export function buildCssSnippet(palette: Palette): string {
  const lines = palette.colors.map((hex, i) => `--color-${i + 1}: ${hex};`);
  return [`/* ${palette.name} */`, ...lines].join('\n');
}

/** Quick perceptual contrast check so a swatch's hex label stays legible against any background color. */
export function getContrastText(hex: string): '#000000' | '#ffffff' {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.6 ? '#000000' : '#ffffff';
}
