import type { FC } from 'react';
import { useMemo } from 'react';
import { Search } from 'lucide-react';
import { Input } from '@/components/ui/input';
import ToolLayout from '@/components/tools/ToolLayout';
import PillGroup from '@/components/tools/PillGroup';
import PaletteCard from '@/components/tools/palette-collection/PaletteCard';
import { usePersistentState } from '@/hooks/usePersistentState';
import palettesData from '@/data/palettes.json';
import {
  CONTRAST_TAG_ORDER,
  HUE_TAG_ORDER,
  PALETTE_TAG_LABELS,
  STYLE_TAG_ORDER,
  type Palette,
  type PaletteTag,
} from '@/lib/palette/types';

const palettes = palettesData as Palette[];

type FilterValue = 'all' | PaletteTag;

const STYLE_OPTIONS: { value: FilterValue; label: string }[] = [
  { value: 'all', label: 'All' },
  ...STYLE_TAG_ORDER.map((tag) => ({ value: tag as FilterValue, label: PALETTE_TAG_LABELS[tag] })),
];
const HUE_OPTIONS: { value: FilterValue; label: string }[] = HUE_TAG_ORDER.map((tag) => ({
  value: tag as FilterValue,
  label: PALETTE_TAG_LABELS[tag],
}));
const CONTRAST_OPTIONS: { value: FilterValue; label: string }[] = CONTRAST_TAG_ORDER.map((tag) => ({
  value: tag as FilterValue,
  label: PALETTE_TAG_LABELS[tag],
}));

const PaletteCollection: FC = () => {
  const [filter, setFilter] = usePersistentState<FilterValue>('palette-collection:filter', 'all');
  const [search, setSearch] = usePersistentState<string>('palette-collection:search', '');

  const filtered = useMemo(() => {
    let result = filter === 'all' ? palettes : palettes.filter((p) => p.tags.includes(filter as PaletteTag));

    const q = search.trim().toLowerCase();
    if (q) {
      result = result.filter(
        (p) =>
          p.name.toLowerCase().includes(q) ||
          p.tags.some((tag) => PALETTE_TAG_LABELS[tag].toLowerCase().includes(q)) ||
          p.colors.some((hex) => hex.toLowerCase().includes(q.replace('#', ''))),
      );
    }

    return result;
  }, [filter, search]);

  return (
    <ToolLayout
      title="Palette Collection"
      description={`Browse ${palettes.length} curated color palettes. Hover any color for its hex code, click to copy it, or copy the whole palette as plain values or CSS variables.`}
    >
      <div className="mb-6 space-y-4">
        <div className="space-y-3">
          <div>
            <span className="block text-xs font-medium text-muted-foreground mb-2">Style</span>
            <PillGroup aria-label="Filter palettes by style" options={STYLE_OPTIONS} value={filter} onChange={setFilter} />
          </div>
          <div>
            <span className="block text-xs font-medium text-muted-foreground mb-2">Hue</span>
            <PillGroup aria-label="Filter palettes by dominant hue" options={HUE_OPTIONS} value={filter} onChange={setFilter} />
          </div>
          <div>
            <span className="block text-xs font-medium text-muted-foreground mb-2">Contrast</span>
            <PillGroup aria-label="Filter palettes by contrast" options={CONTRAST_OPTIONS} value={filter} onChange={setFilter} />
          </div>
        </div>

        <div className="relative max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
          <Input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by name, style, or hex…"
            className="pl-9"
          />
        </div>

        <p className="text-xs text-muted-foreground">
          {filtered.length} palette{filtered.length === 1 ? '' : 's'}
        </p>
      </div>

      {filtered.length === 0 ? (
        <div className="glass-panel p-8 text-center text-sm text-muted-foreground">
          {search.trim() ? `No palettes match "${search.trim()}".` : 'No palettes match this filter.'}
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map((palette) => (
            <PaletteCard key={palette.id} palette={palette} />
          ))}
        </div>
      )}
    </ToolLayout>
  );
};

export default PaletteCollection;
